css:
.sl-footer-student {
    padding-top: 4.5rem;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-footer-student .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-student .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-student.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-student .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }
.sl-footer-student.sl-border,
.sl-footer-student .border.sl-border,
.sl-footer-student .pt-4.sl-border,
.sl-footer-student .border-start.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-student .sl-app-kicker { font-size: 0.75rem; }
.sl-footer-student .sl-footer-link { transition: color 0.2s ease; }
.sl-footer-student .sl-footer-link:hover,
.sl-footer-student .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-student .sl-app-btn {
    transition: border-color 0.2s ease, transform 0.2s ease;
    border-width: 2px !important;
}
.sl-footer-student .sl-app-btn:hover,
.sl-footer-student .sl-app-btn:focus-visible {
    border-color: var(--smartlearn-primary) !important;
    transform: translateY(-2px);
}
.sl-footer-student .sl-dropdown-btn { transition: border-color 0.2s ease; }
.sl-footer-student .sl-dropdown-btn:hover,
.sl-footer-student .sl-dropdown-btn:focus-visible {
    border-color: var(--smartlearn-primary) !important;
}
.sl-footer-student .sl-dropdown-item:hover,
.sl-footer-student .sl-dropdown-item:focus-visible {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent) !important;
    color: var(--smartlearn-primary) !important;
}
.sl-footer-student .sl-social-icon {
    min-width: 40px;
    min-height: 40px;
    transition: color 0.2s ease;
}
.sl-footer-student .sl-social-icon:hover,
.sl-footer-student .sl-social-icon:focus-visible {
    color: var(--smartlearn-primary) !important;
}
.sl-footer-student a:focus-visible,
.sl-footer-student button:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-student .sl-footer-link,
    .sl-footer-student .sl-app-btn,
    .sl-footer-student .sl-dropdown-btn,
    .sl-footer-student .sl-social-icon { transition: none; }
    .sl-footer-student .sl-app-btn:hover,
    .sl-footer-student .sl-app-btn:focus-visible { transform: none; }
}

js:
(function() {
  function initStudentFooters() {
    document.querySelectorAll('.sl-footer-student').forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var wrappers = root.querySelectorAll('.sl-selector-wrapper');
      function closeAll(except) {
        wrappers.forEach(function(w) {
          if (w === except) return;
          var b = w.querySelector('.sl-dropdown-btn');
          var m = w.querySelector('.dropdown-menu');
          if (b) b.setAttribute('aria-expanded', 'false');
          if (m) m.classList.remove('show');
        });
      }
      wrappers.forEach(function(wrapper) {
        var btn = wrapper.querySelector('.sl-dropdown-btn');
        var menu = wrapper.querySelector('.dropdown-menu');
        var label = wrapper.querySelector('.sl-dropdown-label');
        if (!btn || !menu) return;
        btn.addEventListener('click', function(e) {
          e.stopPropagation();
          var isOpen = menu.classList.contains('show');
          closeAll(wrapper);
          menu.classList.toggle('show', !isOpen);
          btn.setAttribute('aria-expanded', isOpen ? 'false' : 'true');
        });
        menu.querySelectorAll('.sl-dropdown-item').forEach(function(item) {
          item.addEventListener('click', function(e) {
            var val = item.getAttribute('data-sl-value') || item.textContent.trim();
            if (label && val) label.textContent = val;
            var href = item.getAttribute('href') || '';
            if (href.indexOf('#') === 0) e.preventDefault();
            menu.classList.remove('show');
            btn.setAttribute('aria-expanded', 'false');
          });
        });
      });
      document.addEventListener('click', function(e) {
        if (!root.contains(e.target)) closeAll(null);
      });
      root.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeAll(null);
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initStudentFooters);
  } else {
    initStudentFooters();
  }
})();
